() => {
 const root=document.body.cloneNode(true);
 root.querySelectorAll('script,style,noscript').forEach(n=>n.remove());
 [root,...root.querySelectorAll('*')].forEach(n=>{
   const sensitive=n.matches('input,textarea,[contenteditable=true],.nav-user-menu__identity');
   for(const a of [...n.attributes]) if(!['id','class','role','type','name','aria-label','aria-expanded','aria-selected','data-testid','placeholder','disabled','hidden'].includes(a.name)) n.removeAttribute(a.name);
   if(sensitive) n.textContent='[MASKED]';
 });
 return root.outerHTML.slice(0,60000);
}

